// Font files imported by URL: Remotion's bundler (webpack asset/resource) turns them into a
// served file and the import into its URL. Narrow on purpose: one pattern per pinned font
// package (docs/ENVIRONMENT.md); other engines' bundlers declare their own asset modules (Vite's `?url`).
declare module '@fontsource-variable/inter/files/*.woff2' {
  const url: string;
  export default url;
}
declare module '@fontsource-variable/noto-serif-sc/files/*.woff2' {
  const url: string;
  export default url;
}
declare module '@fontsource/im-fell-english/files/*.woff2' {
  const url: string;
  export default url;
}
